// Sample data: replace it with your own (a database, an API, another node).
const hours = ['00', '04', '08', '12', '16', '20'];
const orders = [3, 1, 8, 21, 17, 9];
const chart = {
  type: 'line',
  data: { labels: hours, datasets: [{ label: 'Orders', data: orders }] },
  options: { plugins: { title: { display: true, text: 'Orders yesterday, by hour' } } },
};
const imageUrl = 'https://chartpng.dev/chart?w=800&h=450&c=' + encodeURIComponent(JSON.stringify(chart));
const total = orders.reduce((sum, n) => sum + n, 0);
const alt = 'Line chart of orders yesterday by hour. Total: ' + total + '.';
return [{ json: { chart, imageUrl, alt } }];
